export async function getLabProfile(labId: number) {
  const db = await requireDb();
  const [profile] = await db.select().from(labSettings).where(eq(labSettings.labId, labId)).limit(1);
  return profile ?? { id: labId, labId, labName: "", phoneNumber: "", location: "", headerNote1: "", headerNote2: "", headerNote3: "", logoUrl: null, baseCurrencyCode: "YER", updatedAt: new Date() };
}

export async function updateLabProfile(labId: number, input: { labName: string; phoneNumber?: string; location?: string; headerNote1?: string; headerNote2?: string; headerNote3?: string; baseCurrencyCode?: string; logoBase64?: string; logoMime?: "image/jpeg" | "image/png" | "image/webp" }) {
  const db = await requireDb();
  let logoUrl: string | undefined;
  if (input.logoBase64) {
    const imageBytes = Buffer.from(input.logoBase64, "base64");
    if (imageBytes.byteLength > 1_000_000) throw new Error("يرجى اختيار شعار بحجم أصغر من 1 ميغابايت.");
    const extension = input.logoMime === "image/png" ? "png" : input.logoMime === "image/webp" ? "webp" : "jpg";
    logoUrl = (await storagePut(`labs/${labId}/logo.${extension}`, imageBytes, input.logoMime ?? "image/jpeg")).url;
  }
  const values = { id: labId, labId, labName: input.labName.trim(), phoneNumber: input.phoneNumber?.trim() ?? "", location: input.location?.trim() ?? "", headerNote1: input.headerNote1?.trim() ?? "", headerNote2: input.headerNote2?.trim() ?? "", headerNote3: input.headerNote3?.trim() ?? "", baseCurrencyCode: input.baseCurrencyCode ?? "YER", ...(logoUrl ? { logoUrl } : {}) };
  await getCurrency(labId, values.baseCurrencyCode);
  await db.insert(labSettings).values(values).onDuplicateKeyUpdate({ set: { labName: values.labName, phoneNumber: values.phoneNumber, location: values.location, headerNote1: values.headerNote1, headerNote2: values.headerNote2, headerNote3: values.headerNote3, baseCurrencyCode: values.baseCurrencyCode, ...(logoUrl ? { logoUrl } : {}) } });
  await db.update(labs).set({ displayName: values.labName }).where(eq(labs.id, labId));
  return getLabProfile(labId);
}

export async function listClients(labId: number) { const db = await requireDb(); return db.select().from(clients).where(eq(clients.labId, labId)).orderBy(asc(clients.doctorName)); }
export async function getClient(labId: number, id: number) { const db = await requireDb(); const [row] = await db.select().from(clients).where(and(eq(clients.labId, labId), eq(clients.id, id))).limit(1); return row ?? null; }
export async function createClient(labId: number, input: { doctorName: string; clinicName: string; phoneNumber?: string; creditLimit?: string; defaultCurrencyCode?: string }) { const db = await requireDb(); const defaultCurrencyCode = input.defaultCurrencyCode ?? "YER"; await getCurrency(labId, defaultCurrencyCode); const result = await db.insert(clients).values({ labId, doctorName: input.doctorName, clinicName: input.clinicName, phoneNumber: input.phoneNumber || null, creditLimit: input.creditLimit ?? "0.00", defaultCurrencyCode }); return Number(result[0].insertId); }
export async function updateClient(labId: number, id: number, input: { doctorName: string; clinicName: string; phoneNumber?: string; creditLimit?: string }) { const db = await requireDb(); await ensureOwned(clients, labId, id, "الطبيب أو العيادة"); await db.update(clients).set({ doctorName: input.doctorName, clinicName: input.clinicName, phoneNumber: input.phoneNumber || null, creditLimit: input.creditLimit ?? "0.00" }).where(and(eq(clients.labId, labId), eq(clients.id, id))); return { success: true }; }
export async function deleteClient(labId: number, id: number) { const db = await requireDb(); await ensureOwned(clients, labId, id, "الطبيب أو العيادة"); const [orderRef] = await db.select({ id: orders.id }).from(orders).where(and(eq(orders.labId, labId), eq(orders.clientId, id))).limit(1); const [paymentRef] = await db.select({ id: payments.id }).from(payments).where(and(eq(payments.labId, labId), eq(payments.clientId, id))).limit(1); if (orderRef || paymentRef) throw new Error("لا يمكن حذف الطبيب أو العيادة لوجود حالات أو سندات قبض مرتبطة به."); await db.delete(clients).where(and(eq(clients.labId, labId), eq(clients.id, id))); return { success: true }; }

export async function listServices(labId: number) { await ensureServiceSeed(labId); const db = await requireDb(); return db.select().from(services).where(eq(services.labId, labId)).orderBy(asc(services.category), asc(services.serviceName)); }
export async function createService(labId: number, input: { category: string; serviceName: string; basePrice: string; urgentPrice: string }) { const db = await requireDb(); const result = await db.insert(services).values({ labId, ...input }); return Number(result[0].insertId); }
export async function updateServicePrice(labId: number, id: number, input: { basePrice: string; urgentPrice: string }) { const db = await requireDb(); await ensureOwned(services, labId, id, "الخدمة"); await db.update(services).set(input).where(and(eq(services.labId, labId), eq(services.id, id))); return { success: true }; }
export async function deleteService(labId: number, id: number) { const db = await requireDb(); await ensureOwned(services, labId, id, "الخدمة"); const [orderRef] = await db.select({ id: orders.id }).from(orders).where(and(eq(orders.labId, labId), eq(orders.serviceId, id))).limit(1); if (orderRef) throw new Error("لا يمكن حذف الخدمة لأنها مستخدمة في حالات مسجلة."); await db.delete(services).where(and(eq(services.labId, labId), eq(services.id, id))); return { success: true }; }

