export async function deleteTechnician(labId: number, id: number) { const db = await requireDb(); await ensureOwned(technicians, labId, id, "الفني"); const [assignmentRef] = await db.select({ id: orderTechnicians.id }).from(orderTechnicians).where(and(eq(orderTechnicians.labId, labId), eq(orderTechnicians.technicianId, id))).limit(1); const [payoutRef] = await db.select({ id: technicianPayouts.id }).from(technicianPayouts).where(and(eq(technicianPayouts.labId, labId), eq(technicianPayouts.technicianId, id))).limit(1); const [workRef] = await db.select({ id: technicianWorkEntries.id }).from(technicianWorkEntries).where(and(eq(technicianWorkEntries.labId, labId), eq(technicianWorkEntries.technicianId, id))).limit(1); if (assignmentRef || payoutRef || workRef) throw new Error("لا يمكن حذف الفني لوجود إنجازات أو صرفيات أو حالات مرتبطة به."); await db.delete(technicians).where(and(eq(technicians.labId, labId), eq(technicians.id, id))); return { success: true }; }
export async function upsertTechnicianRate(labId: number, input: { technicianId: number; serviceId: number; ratePerTooth: string }) { const db = await requireDb(); await ensureOwned(technicians, labId, input.technicianId, "الفني"); await ensureOwned(services, labId, input.serviceId, "الخدمة"); await db.insert(technicianRates).values({ labId, ...input }).onDuplicateKeyUpdate({ set: { ratePerTooth: input.ratePerTooth } }); return { success: true }; }

type OrderWriteInput = { invoiceNumber: string; clientId: number; patientName?: string; orderDate: string; orderType: "normal" | "urgent" | "adjustment"; serviceId: number; upperRight?: string; upperLeft?: string; lowerRight?: string; lowerLeft?: string; teethCount: number; unitPrice: string; currencyCode?: string; notes?: string };
const orderValues = (input: OrderWriteInput) => ({ ...input, invoiceNumber: input.invoiceNumber.trim(), caseMonth: input.orderDate.slice(0, 7), patientName: input.patientName?.trim() || null, upperRight: input.upperRight || "", upperLeft: input.upperLeft || "", lowerRight: input.lowerRight || "", lowerLeft: input.lowerLeft || "", notes: input.notes?.trim() || null });

export async function listOrders(labId: number, clientId?: number) { const db = await requireDb(); const base = db.select({ id: orders.id, invoiceNumber: orders.invoiceNumber, patientName: orders.patientName, orderDate: orders.orderDate, caseMonth: orders.caseMonth, orderType: orders.orderType, orderStatus: orders.orderStatus, teethCount: orders.teethCount, unitPrice: orders.unitPrice, totalAmount: orders.totalAmount, currencyCode: orders.currencyCode, notes: orders.notes, clientId: clients.id, doctorName: clients.doctorName, clinicName: clients.clinicName, serviceId: services.id, category: services.category, serviceName: services.serviceName }).from(orders).innerJoin(clients, eq(orders.clientId, clients.id)).innerJoin(services, eq(orders.serviceId, services.id)); const condition = clientId ? and(eq(orders.labId, labId), eq(orders.clientId, clientId)) : eq(orders.labId, labId); return base.where(condition).orderBy(desc(orders.orderDate), desc(orders.id)); }
export async function getOrder(labId: number, id: number) { const db = await requireDb(); const [row] = await db.select().from(orders).where(and(eq(orders.labId, labId), eq(orders.id, id))).limit(1); return row ?? null; }
export async function createOrder(labId: number, input: OrderWriteInput) { const db = await requireDb(); await ensureOwned(clients, labId, input.clientId, "الطبيب أو العيادة"); await ensureOwned(services, labId, input.serviceId, "الخدمة"); const currency = await getCurrency(labId, input.currencyCode ?? "YER"); const result = await db.insert(orders).values({ labId, ...orderValues({ ...input, currencyCode: currency.currencyCode }), exchangeRate: currency.exchangeRate }); await recalculateClientBalance(labId, input.clientId); return Number(result[0].insertId); }
export async function updateOrder(labId: number, id: number, input: OrderWriteInput) { const db = await requireDb(); const [previous] = await db.select({ clientId: orders.clientId }).from(orders).where(and(eq(orders.labId, labId), eq(orders.id, id))).limit(1); if (!previous) throw new Error("الحالة المطلوبة غير موجودة."); await ensureOwned(clients, labId, input.clientId, "الطبيب أو العيادة"); await ensureOwned(services, labId, input.serviceId, "الخدمة"); const currency = await getCurrency(labId, input.currencyCode ?? "YER"); await db.update(orders).set({ ...orderValues({ ...input, currencyCode: currency.currencyCode }), exchangeRate: currency.exchangeRate }).where(and(eq(orders.labId, labId), eq(orders.id, id))); await recalculateClientBalance(labId, previous.clientId); if (previous.clientId !== input.clientId) await recalculateClientBalance(labId, input.clientId); return { success: true }; }
export async function updateOrderStatus(labId: number, id: number, orderStatus: "new" | "in_progress" | "completed" | "delivered") { const db = await requireDb(); await db.update(orders).set({ orderStatus }).where(and(eq(orders.labId, labId), eq(orders.id, id))); return { success: true }; }
export async function deleteOrder(labId: number, id: number) { const db = await requireDb(); const [order] = await db.select({ clientId: orders.clientId }).from(orders).where(and(eq(orders.labId, labId), eq(orders.id, id))).limit(1); if (!order) throw new Error("الحالة المطلوبة غير موجودة."); await db.delete(orders).where(and(eq(orders.labId, labId), eq(orders.id, id))); await recalculateClientBalance(labId, order.clientId); return { success: true }; }

export async function recalculateClientBalance(labId: number, clientId: number) { const db = await requireDb(); const [ordersTotal] = await db.select({ total: sql<string>`COALESCE(SUM(${orders.totalAmount} * ${orders.exchangeRate}), 0)` }).from(orders).where(and(eq(orders.labId, labId), eq(orders.clientId, clientId))); const [paymentsTotal] = await db.select({ total: sql<string>`COALESCE(SUM((${payments.amountPaid} + ${payments.discount}) * ${payments.exchangeRate}), 0)` }).from(payments).where(and(eq(payments.labId, labId), eq(payments.clientId, clientId))); const balance = calculateClientBalance(ordersTotal?.total, paymentsTotal?.total, 0); await db.update(clients).set({ currentBalance: balance }).where(and(eq(clients.labId, labId), eq(clients.id, clientId))); return balance; }
export async function recalculateTechnicianBalance(labId: number, technicianId: number) { const db = await requireDb(); const [earned] = await db.select({ total: sql<string>`COALESCE(SUM(${orderTechnicians.commissionEarned}), 0)` }).from(orderTechnicians).where(and(eq(orderTechnicians.labId, labId), eq(orderTechnicians.technicianId, technicianId))); const [paid] = await db.select({ total: sql<string>`COALESCE(SUM(${technicianPayouts.amountPaid}), 0)` }).from(technicianPayouts).where(and(eq(technicianPayouts.labId, labId), eq(technicianPayouts.technicianId, technicianId))); const [manualWork] = await db.select({ total: sql<string>`COALESCE(SUM(${technicianWorkEntries.totalAmount}), 0)` }).from(technicianWorkEntries).where(and(eq(technicianWorkEntries.labId, labId), eq(technicianWorkEntries.technicianId, technicianId))); const balance = calculateTechnicianBalance(Number(earned?.total ?? 0) + Number(manualWork?.total ?? 0), paid?.total); await db.update(technicians).set({ currentBalance: balance }).where(and(eq(technicians.labId, labId), eq(technicians.id, technicianId))); return balance; }
export async function assignTechnician(labId: number, input: { orderId: number; technicianId: number; stageName: "wax" | "ceramic" | "finishing" | "fitting" | "other"; assignedTeeth: number }) { const db = await requireDb(); const [order] = await db.select().from(orders).where(and(eq(orders.labId, labId), eq(orders.id, input.orderId))).limit(1); const [technician] = await db.select().from(technicians).where(and(eq(technicians.labId, labId), eq(technicians.id, input.technicianId))).limit(1); if (!order || !technician) throw new Error("تعذر العثور على الحالة أو الفني."); const [customRate] = await db.select().from(technicianRates).where(and(eq(technicianRates.labId, labId), eq(technicianRates.technicianId, input.technicianId), eq(technicianRates.serviceId, order.serviceId))).limit(1); const commission = calculateCommission({ assignedTeeth: input.assignedTeeth, unitPrice: order.unitPrice, commissionType: technician.commissionType, commissionRate: customRate ? Number(customRate.ratePerTooth) : Number(technician.commissionRate), customRate: customRate?.ratePerTooth }); const result = await db.insert(orderTechnicians).values({ labId, ...input, commissionEarned: commission }); await recalculateTechnicianBalance(labId, input.technicianId); return Number(result[0].insertId); }

export async function createPayment(labId: number, input: { clientId: number; paymentDate: string; amountPaid: string; discount: string; paymentMethod: "cash" | "bank" | "pos"; cashboxId: number; currencyCode?: string; notes?: string }) { const db = await requireDb(); await ensureOwned(clients, labId, input.clientId, "الطبيب أو العيادة"); const currency = await getCurrency(labId, input.currencyCode ?? "YER"); await getOwnedCashbox(labId, input.cashboxId, currency.currencyCode); const [sequence] = await db.select({ nextReceipt: sql<number>`COALESCE(MAX(${payments.receiptNumber}), 0) + 1` }).from(payments).where(eq(payments.labId, labId)); const receiptNumber = Number(sequence?.nextReceipt ?? 1); const result = await db.insert(payments).values({ labId, ...input, currencyCode: currency.currencyCode, exchangeRate: currency.exchangeRate, receiptNumber, notes: input.notes || null }); await recalculateClientBalance(labId, input.clientId); await recalculateCashboxBalance(labId, input.cashboxId); return { id: Number(result[0].insertId), receiptNumber }; }
export async function updatePayment(labId: number, id: number, input: { clientId: number; paymentDate: string; amountPaid: string; discount: string; paymentMethod: "cash" | "bank" | "pos"; cashboxId: number; currencyCode: string; notes?: string }) { const db = await requireDb(); const [previous] = await db.select({ clientId: payments.clientId, cashboxId: payments.cashboxId }).from(payments).where(and(eq(payments.labId, labId), eq(payments.id, id))).limit(1); if (!previous) throw new Error("سند القبض غير موجود."); await ensureOwned(clients, labId, input.clientId, "الطبيب أو العيادة"); const currency = await getCurrency(labId, input.currencyCode); await getOwnedCashbox(labId, input.cashboxId, currency.currencyCode); await db.update(payments).set({ ...input, currencyCode: currency.currencyCode, exchangeRate: currency.exchangeRate, notes: input.notes?.trim() || null }).where(and(eq(payments.labId, labId), eq(payments.id, id))); await recalculateClientBalance(labId, previous.clientId); if (previous.clientId !== input.clientId) await recalculateClientBalance(labId, input.clientId); if (previous.cashboxId) await recalculateCashboxBalance(labId, previous.cashboxId); if (previous.cashboxId !== input.cashboxId) await recalculateCashboxBalance(labId, input.cashboxId); return { success: true }; }
export async function deletePayment(labId: number, id: number) { const db = await requireDb(); const [row] = await db.select({ clientId: payments.clientId, cashboxId: payments.cashboxId }).from(payments).where(and(eq(payments.labId, labId), eq(payments.id, id))).limit(1); if (!row) throw new Error("سند القبض غير موجود."); await db.delete(payments).where(and(eq(payments.labId, labId), eq(payments.id, id))); await recalculateClientBalance(labId, row.clientId); if (row.cashboxId) await recalculateCashboxBalance(labId, row.cashboxId); return { success: true }; }
export async function listPayments(labId: number, clientId?: number) { const db = await requireDb(); const query = db.select({ id: payments.id, receiptNumber: payments.receiptNumber, clientId: clients.id, doctorName: clients.doctorName, clinicName: clients.clinicName, paymentDate: payments.paymentDate, amountPaid: payments.amountPaid, discount: payments.discount, paymentMethod: payments.paymentMethod, cashboxId: payments.cashboxId, currencyCode: payments.currencyCode, notes: payments.notes }).from(payments).innerJoin(clients, eq(payments.clientId, clients.id)); return query.where(clientId ? and(eq(payments.labId, labId), eq(payments.clientId, clientId)) : eq(payments.labId, labId)).orderBy(desc(payments.id)); }

