export async function getDoctorLedger(labId: number, clientId: number, startDate?: string, endDate?: string, currencyCode?: string) { const db = await requireDb(); const [client] = await db.select().from(clients).where(and(eq(clients.labId, labId), eq(clients.id, clientId))).limit(1); if (!client) throw new Error("الطبيب أو العيادة غير موجودة."); const conditions = [eq(orders.labId, labId), eq(orders.clientId, clientId)]; if (startDate) conditions.push(gte(orders.orderDate, startDate)); if (endDate) conditions.push(lte(orders.orderDate, endDate)); if (currencyCode) conditions.push(eq(orders.currencyCode, currencyCode)); const items = await db.select({ invoiceNumber: orders.invoiceNumber, orderDate: orders.orderDate, notes: orders.notes, patientName: orders.patientName, orderType: orders.orderType, category: services.category, serviceName: services.serviceName, upperRight: orders.upperRight, upperLeft: orders.upperLeft, lowerRight: orders.lowerRight, lowerLeft: orders.lowerLeft, teethCount: orders.teethCount, unitPrice: orders.unitPrice, totalAmount: orders.totalAmount, currencyCode: orders.currencyCode }).from(orders).innerJoin(services, eq(orders.serviceId, services.id)).where(and(...conditions)).orderBy(asc(orders.orderDate), asc(orders.createdAt)); const paymentConditions = [eq(payments.labId, labId), eq(payments.clientId, clientId)]; if (startDate) paymentConditions.push(gte(payments.paymentDate, startDate)); if (endDate) paymentConditions.push(lte(payments.paymentDate, endDate)); if (currencyCode) paymentConditions.push(eq(payments.currencyCode, currencyCode)); const paymentItems = await db.select({ receiptNumber: payments.receiptNumber, paymentDate: payments.paymentDate, amountPaid: payments.amountPaid, discount: payments.discount, paymentMethod: payments.paymentMethod, currencyCode: payments.currencyCode, notes: payments.notes }).from(payments).where(and(...paymentConditions)).orderBy(asc(payments.paymentDate), asc(payments.id)); const totalAmount = items.reduce((sum, item) => sum + Number(item.totalAmount ?? 0), 0); const totalPayments = paymentItems.reduce((sum, item) => sum + Number(item.amountPaid ?? 0) + Number(item.discount ?? 0), 0); return { client, currencyCode: currencyCode ?? "ALL", items, payments: paymentItems, totals: { totalAmount: money(totalAmount), totalPayments: money(totalPayments), remainingAmount: money(totalAmount - totalPayments) } }; }
export async function getTechnicianLedger(labId: number, technicianId: number, startDate: string, endDate: string) { const db = await requireDb(); const [technician] = await db.select().from(technicians).where(and(eq(technicians.labId, labId), eq(technicians.id, technicianId))).limit(1); if (!technician) throw new Error("الفني غير موجود."); const manualWork = await db.select({ workDate: technicianWorkEntries.workDate, piecesCount: technicianWorkEntries.piecesCount, unitRate: technicianWorkEntries.unitRate, totalAmount: technicianWorkEntries.totalAmount, notes: technicianWorkEntries.notes }).from(technicianWorkEntries).where(and(eq(technicianWorkEntries.labId, labId), eq(technicianWorkEntries.technicianId, technicianId), gte(technicianWorkEntries.workDate, startDate), lte(technicianWorkEntries.workDate, endDate))).orderBy(asc(technicianWorkEntries.workDate), asc(technicianWorkEntries.id)); const payouts = await db.select({ payoutDate: technicianPayouts.payoutDate, amountPaid: technicianPayouts.amountPaid, notes: technicianPayouts.notes }).from(technicianPayouts).where(and(eq(technicianPayouts.labId, labId), eq(technicianPayouts.technicianId, technicianId), gte(technicianPayouts.payoutDate, startDate), lte(technicianPayouts.payoutDate, endDate))).orderBy(asc(technicianPayouts.payoutDate), asc(technicianPayouts.id)); const workTotal = manualWork.reduce((sum, item) => sum + Number(item.totalAmount ?? 0), 0); const paidTotal = payouts.reduce((sum, item) => sum + Number(item.amountPaid ?? 0), 0); return { technician, manualWork, payouts, totals: { workTotal: money(workTotal), paidTotal: money(paidTotal), remainingAmount: money(workTotal - paidTotal) } }; }
export async function getSupplierLedger(labId: number, supplierId: number, startDate: string, endDate: string) { const db = await requireDb(); const [supplier] = await db.select().from(suppliers).where(and(eq(suppliers.labId, labId), eq(suppliers.id, supplierId))).limit(1); if (!supplier) throw new Error("المورد غير موجود."); const materials = await db.select({ materialDate: supplierMaterials.materialDate, materialDescription: supplierMaterials.materialDescription, amount: supplierMaterials.amount, notes: supplierMaterials.notes }).from(supplierMaterials).where(and(eq(supplierMaterials.labId, labId), eq(supplierMaterials.supplierId, supplierId), gte(supplierMaterials.materialDate, startDate), lte(supplierMaterials.materialDate, endDate))).orderBy(asc(supplierMaterials.materialDate), asc(supplierMaterials.id)); const paymentRows = await db.select({ paymentDate: supplierPayments.paymentDate, amountPaid: supplierPayments.amountPaid, notes: supplierPayments.notes }).from(supplierPayments).where(and(eq(supplierPayments.labId, labId), eq(supplierPayments.supplierId, supplierId), gte(supplierPayments.paymentDate, startDate), lte(supplierPayments.paymentDate, endDate))).orderBy(asc(supplierPayments.paymentDate), asc(supplierPayments.id)); const materialsTotal = materials.reduce((total, item) => total + Number(item.amount ?? 0), 0); const paidTotal = paymentRows.reduce((total, item) => total + Number(item.amountPaid ?? 0), 0); return { supplier, materials, payments: paymentRows, totals: { materialsTotal: money(materialsTotal), paidTotal: money(paidTotal), remainingAmount: money(materialsTotal - paidTotal) } }; }
export async function listClientsWithOrders(labId: number, startDate: string, endDate: string) { const db = await requireDb(); return db.select({ id: clients.id, doctorName: clients.doctorName, clinicName: clients.clinicName }).from(clients).innerJoin(orders, eq(orders.clientId, clients.id)).where(and(eq(orders.labId, labId), gte(orders.orderDate, startDate), lte(orders.orderDate, endDate))).groupBy(clients.id, clients.doctorName, clients.clinicName).orderBy(asc(clients.doctorName)); }
export async function getPeriodSummary(labId: number, startDate: string, endDate: string, currencyCode?: string) { const db = await requireDb(); const condition = currencyCode ? and(eq(orders.labId, labId), gte(orders.orderDate, startDate), lte(orders.orderDate, endDate), eq(orders.currencyCode, currencyCode)) : and(eq(orders.labId, labId), gte(orders.orderDate, startDate), lte(orders.orderDate, endDate)); const [totals] = await db.select({ casesCount: sql<number>`COUNT(${orders.id})`, piecesCount: sql<number>`COALESCE(SUM(${orders.teethCount}), 0)`, revenue: sql<string>`COALESCE(SUM(${orders.totalAmount}), 0)` }).from(orders).where(condition); const breakdown = await db.select({ category: services.category, orderType: orders.orderType, casesCount: sql<number>`COUNT(${orders.id})`, piecesCount: sql<number>`COALESCE(SUM(${orders.teethCount}), 0)`, revenue: sql<string>`COALESCE(SUM(${orders.totalAmount}), 0)` }).from(orders).innerJoin(services, eq(orders.serviceId, services.id)).where(condition).groupBy(services.category, orders.orderType).orderBy(asc(services.category), asc(orders.orderType)); return { startDate, endDate, currencyCode: currencyCode ?? "ALL", totals: { casesCount: Number(totals?.casesCount ?? 0), piecesCount: Number(totals?.piecesCount ?? 0), revenue: money(totals?.revenue ?? 0) }, breakdown }; }
export async function getProfitLoss(labId: number, startDate: string, endDate: string, currencyCode?: string, cashboxId?: number) { const db = await requireDb(); const orderConditions = [eq(orders.labId, labId), gte(orders.orderDate, startDate), lte(orders.orderDate, endDate)]; const materialConditions = [eq(supplierMaterials.labId, labId), gte(supplierMaterials.materialDate, startDate), lte(supplierMaterials.materialDate, endDate)]; const expenseConditions = [eq(expenses.labId, labId), gte(expenses.expenseDate, startDate), lte(expenses.expenseDate, endDate)]; if (currencyCode) { orderConditions.push(eq(orders.currencyCode, currencyCode)); materialConditions.push(eq(supplierMaterials.currencyCode, currencyCode)); expenseConditions.push(eq(expenses.currencyCode, currencyCode)); } const [revenue] = await db.select({ piecesCount: sql<number>`COALESCE(SUM(${orders.teethCount}), 0)`, total: sql<string>`COALESCE(SUM(${orders.totalAmount}), 0)` }).from(orders).where(and(...orderConditions)); const [supplierMaterialsTotal] = await db.select({ total: sql<string>`COALESCE(SUM(${supplierMaterials.amount}), 0)` }).from(supplierMaterials).where(and(...materialConditions)); const expensesByType = await db.select({ costType: expenses.costType, total: sql<string>`COALESCE(SUM(${expenses.amount}), 0)` }).from(expenses).where(and(...expenseConditions)).groupBy(expenses.costType); const sum = (type: "materials" | "wages" | "rent" | "installments" | "utilities" | "other") => expensesByType.filter((item) => item.costType === type).reduce((total, item) => total + Number(item.total ?? 0), 0); const totalRevenue = Number(revenue?.total ?? 0); const costs = { materials: Number(supplierMaterialsTotal?.total ?? 0) + sum("materials"), wages: sum("wages"), rent: sum("rent"), installments: sum("installments"), utilities: sum("utilities"), other: sum("other") }; const totalCosts = Object.values(costs).reduce((total, value) => total + value, 0); const paymentConditions = [eq(payments.labId, labId), gte(payments.paymentDate, startDate), lte(payments.paymentDate, endDate)]; const payoutConditions = [eq(technicianPayouts.labId, labId), gte(technicianPayouts.payoutDate, startDate), lte(technicianPayouts.payoutDate, endDate)]; const cashExpenseConditions = [eq(expenses.labId, labId), gte(expenses.expenseDate, startDate), lte(expenses.expenseDate, endDate)]; const supplierPaymentConditions = [eq(supplierPayments.labId, labId), gte(supplierPayments.paymentDate, startDate), lte(supplierPayments.paymentDate, endDate)]; const incomingConditions = [eq(cashboxTransfers.labId, labId), gte(cashboxTransfers.transferDate, startDate), lte(cashboxTransfers.transferDate, endDate)]; const outgoingConditions = [eq(cashboxTransfers.labId, labId), gte(cashboxTransfers.transferDate, startDate), lte(cashboxTransfers.transferDate, endDate)]; if (currencyCode) { paymentConditions.push(eq(payments.currencyCode, currencyCode)); payoutConditions.push(eq(technicianPayouts.currencyCode, currencyCode)); cashExpenseConditions.push(eq(expenses.currencyCode, currencyCode)); supplierPaymentConditions.push(eq(supplierPayments.currencyCode, currencyCode)); incomingConditions.push(eq(cashboxTransfers.currencyCode, currencyCode)); outgoingConditions.push(eq(cashboxTransfers.currencyCode, currencyCode)); } if (cashboxId) { paymentConditions.push(eq(payments.cashboxId, cashboxId)); payoutConditions.push(eq(technicianPayouts.cashboxId, cashboxId)); cashExpenseConditions.push(eq(expenses.cashboxId, cashboxId)); supplierPaymentConditions.push(eq(supplierPayments.cashboxId, cashboxId)); incomingConditions.push(eq(cashboxTransfers.toCashboxId, cashboxId)); outgoingConditions.push(eq(cashboxTransfers.fromCashboxId, cashboxId)); } const [[received], [technicianPaid], [operatingPaid], [supplierPaid], [incoming], [outgoing]] = await Promise.all([db.select({ total: sql<string>`COALESCE(SUM(${payments.amountPaid}), 0)` }).from(payments).where(and(...paymentConditions)), db.select({ total: sql<string>`COALESCE(SUM(${technicianPayouts.amountPaid}), 0)` }).from(technicianPayouts).where(and(...payoutConditions)), db.select({ total: sql<string>`COALESCE(SUM(${expenses.amount}), 0)` }).from(expenses).where(and(...cashExpenseConditions)), db.select({ total: sql<string>`COALESCE(SUM(${supplierPayments.amountPaid}), 0)` }).from(supplierPayments).where(and(...supplierPaymentConditions)), db.select({ total: sql<string>`COALESCE(SUM(${cashboxTransfers.amount}), 0)` }).from(cashboxTransfers).where(and(...incomingConditions)), db.select({ total: sql<string>`COALESCE(SUM(${cashboxTransfers.amount}), 0)` }).from(cashboxTransfers).where(and(...outgoingConditions))]); const receivedValue = Number(received?.total ?? 0); const paidValue = Number(technicianPaid?.total ?? 0) + Number(operatingPaid?.total ?? 0) + Number(supplierPaid?.total ?? 0); const incomingValue = Number(incoming?.total ?? 0); const outgoingValue = Number(outgoing?.total ?? 0); return { startDate, endDate, currencyCode: currencyCode ?? "ALL", cashboxId: cashboxId ?? null, piecesCount: Number(revenue?.piecesCount ?? 0), revenue: money(totalRevenue), totalCosts: money(totalCosts), netResult: money(totalRevenue - totalCosts), costs: Object.fromEntries(Object.entries(costs).map(([key, value]) => [key, money(value)])) as Record<keyof typeof costs, string>, cashflow: { received: money(receivedValue), paid: money(paidValue), incoming: money(incomingValue), outgoing: money(outgoingValue), net: money(receivedValue - paidValue + incomingValue - outgoingValue) } }; }
export async function getDashboard(labId: number) { const db = await requireDb(); const [balances] = await db.select({ receivable: sql<string>`COALESCE(SUM(${clients.currentBalance}), 0)`, clientsCount: sql<number>`COUNT(${clients.id})` }).from(clients).where(eq(clients.labId, labId)); const [statusCounts] = await db.select({ inProgress: sql<number>`SUM(CASE WHEN ${orders.orderStatus} = 'in_progress' THEN 1 ELSE 0 END)`, newOrders: sql<number>`SUM(CASE WHEN ${orders.orderStatus} = 'new' THEN 1 ELSE 0 END)` }).from(orders).where(eq(orders.labId, labId)); const [expenseTotal] = await db.select({ total: sql<string>`COALESCE(SUM(${expenses.amount}), 0)` }).from(expenses).where(eq(expenses.labId, labId)); return { receivable: money(Number(balances?.receivable ?? 0)), clientsCount: Number(balances?.clientsCount ?? 0), inProgress: Number(statusCounts?.inProgress ?? 0), newOrders: Number(statusCounts?.newOrders ?? 0), expenseTotal: money(Number(expenseTotal?.total ?? 0)) }; }
export async function getBootstrapData(labId: number) { await ensureServiceSeed(labId); const [dashboard, clientList, serviceList, technicianList, orderList, paymentList, expenseList] = await Promise.all([getDashboard(labId), listClients(labId), listServices(labId), listTechnicians(labId), listOrders(labId), listPayments(labId), listExpenses(labId)]); return { dashboard, clients: clientList, services: serviceList, technicians: technicianList, orders: orderList, payments: paymentList, expenses: expenseList }; }

export async function authenticateLabUser(input: { credential: string; password: string; deviceId: string; deviceLabel?: string }) {
  const db = await requireDb();
  const credential = input.credential.trim();
  const [user] = await db.select({ id: labUsers.id, labId: labUsers.labId, username: labUsers.username, passwordHash: labUsers.passwordHash, role: labUsers.role, userActive: labUsers.isActive, sessionVersion: labUsers.sessionVersion, mustChangePassword: labUsers.mustChangePassword, labActive: labs.isActive, maxDevices: labUsers.maxDevices, labMaxDevices: labs.maxDevices, subscriptionEndDate: labs.subscriptionEndDate }).from(labUsers).leftJoin(labs, eq(labUsers.labId, labs.id)).where(or(eq(labUsers.username, credential), eq(labUsers.email, credential))).limit(1);
  if (!user || !verifyPassword(input.password, user.passwordHash)) throw new Error("بيانات الدخول غير صحيحة.");
  if (!user.userActive) throw new Error("هذا الحساب موقوف. يرجى التواصل مع الدعم.");
  if (user.role === "lab_user") {
    if (!user.labId || !user.labActive) throw new Error("اشتراك المختبر غير مفعل حاليًا. يرجى التواصل مع الدعم.");
    if (isSubscriptionExpired(user.subscriptionEndDate)) throw new Error("انتهى اشتراك المختبر. يرجى التواصل مع الدعم لتجديد الاشتراك.");
    const fingerprint = fingerprintDevice(input.deviceId);
    const [registered] = await db.select({ id: labDevices.id }).from(labDevices).where(and(eq(labDevices.labId, user.labId), eq(labDevices.deviceFingerprint, fingerprint))).limit(1);
    if (registered) await db.update(labDevices).set({ deviceLabel: input.deviceLabel?.slice(0, 120) || null }).where(eq(labDevices.id, registered.id));
    else {
      const [count] = await db.select({ total: sql<number>`COUNT(${labDevices.id})` }).from(labDevices).where(eq(labDevices.labId, user.labId));
      if (Number(count?.total ?? 0) >= Number(user.maxDevices ?? user.labMaxDevices ?? 1)) throw new Error("تم الوصول إلى الحد المسموح من الأجهزة لهذا الاشتراك. يرجى التواصل مع الدعم.");
      await db.insert(labDevices).values({ labId: user.labId, deviceFingerprint: fingerprint, deviceLabel: input.deviceLabel?.slice(0, 120) || null });
    }
  }
  await db.update(labUsers).set({ lastSignedIn: new Date() }).where(eq(labUsers.id, user.id));
  const session = { userId: user.id, labId: user.labId, role: user.role, username: user.username, sessionVersion: user.sessionVersion } as LabSession;
  return { token: await createLabSession(session), session: { ...session, mustChangePassword: user.mustChangePassword } };
}

export async function validateLabSession(session: LabSession) {
  const db = await requireDb();
  const [row] = await db.select({ id: labUsers.id, labId: labUsers.labId, username: labUsers.username, role: labUsers.role, userActive: labUsers.isActive, sessionVersion: labUsers.sessionVersion, mustChangePassword: labUsers.mustChangePassword, labActive: labs.isActive, subscriptionEndDate: labs.subscriptionEndDate, displayName: labs.displayName }).from(labUsers).leftJoin(labs, eq(labUsers.labId, labs.id)).where(eq(labUsers.id, session.userId)).limit(1);
  if (!row || !row.userActive || row.role !== session.role || row.labId !== session.labId || row.sessionVersion !== session.sessionVersion) throw new Error("انتهت صلاحية الجلسة. يرجى تسجيل الدخول من جديد.");
  if (row.role === "lab_user" && !row.labActive) throw new Error("اشتراك المختبر غير مفعل حاليًا.");
  if (row.role === "lab_user" && isSubscriptionExpired(row.subscriptionEndDate)) throw new Error("انتهى اشتراك المختبر. يرجى التواصل مع الدعم لتجديد الاشتراك.");
  return { userId: row.id, labId: row.labId, role: row.role, username: row.username, sessionVersion: row.sessionVersion, mustChangePassword: row.mustChangePassword, labName: row.displayName ?? null };
}

export async function hasPlatformAdmin() { const db = await requireDb(); const [row] = await db.select({ id: labUsers.id }).from(labUsers).where(eq(labUsers.role, "admin")).limit(1); return Boolean(row); }
export async function bootstrapAdmin(input: { username: string; email?: string; password: string; setupCode: string }) { if (input.setupCode !== process.env.LAB_ADMIN_SETUP_CODE) throw new Error("رمز إعداد المسؤول غير صحيح."); if (await hasPlatformAdmin()) throw new Error("تم إعداد حساب المسؤول بالفعل."); const db = await requireDb(); const result = await db.insert(labUsers).values({ labId: null, username: input.username.trim(), email: input.email?.trim() || null, passwordHash: hashPassword(input.password), role: "admin" }); return Number(result[0].insertId); }
export async function resetPlatformAdminEmergency(input: { emergencyCode: string; password: string }) { if (!verifyAdminEmergencyCode(input.emergencyCode)) throw new Error("رمز الطوارئ غير صحيح."); const db = await requireDb(); const [admin] = await db.select({ id: labUsers.id }).from(labUsers).where(eq(labUsers.role, "admin")).limit(1); if (!admin) throw new Error("حساب المسؤول غير مهيأ بعد."); await db.update(labUsers).set({ passwordHash: hashPassword(input.password), mustChangePassword: false, sessionVersion: sql`${labUsers.sessionVersion} + 1` }).where(eq(labUsers.id, admin.id)); return { success: true } as const; }
export async function listLabsAdmin() { const db = await requireDb(); const labList = await db.select().from(labs).orderBy(desc(labs.createdAt)); const results = []; for (const lab of labList) { const [deviceCount] = await db.select({ total: sql<number>`COUNT(${labDevices.id})` }).from(labDevices).where(eq(labDevices.labId, lab.id)); const [userCount] = await db.select({ total: sql<number>`COUNT(${labUsers.id})` }).from(labUsers).where(eq(labUsers.labId, lab.id)); results.push({ ...lab, subscriptionState: isSubscriptionExpired(lab.subscriptionEndDate) ? "expired" : lab.isActive ? "active" : "suspended", deviceCount: Number(deviceCount?.total ?? 0), userCount: Number(userCount?.total ?? 0) }); } return results; }
export async function createLabAdmin(input: { labCode: string; displayName: string; maxDevices: number; username: string; email?: string; password: string; subscriptionStartDate?: string; subscriptionEndDate?: string }) { const db = await requireDb(); const startDate = input.subscriptionStartDate ?? new Date().toISOString().slice(0, 10); const endDate = input.subscriptionEndDate ?? `${Number(startDate.slice(0, 4)) + 1}${startDate.slice(4)}`; const result = await db.insert(labs).values({ labCode: input.labCode.trim().toLowerCase(), displayName: input.displayName.trim(), maxDevices: input.maxDevices, isActive: true, subscriptionStartDate: startDate, subscriptionEndDate: endDate }); const labId = Number(result[0].insertId); await db.insert(labSettings).values({ id: labId, labId, labName: input.displayName.trim() }); await db.insert(labUsers).values({ labId, username: input.username.trim(), email: input.email?.trim() || null, passwordHash: hashPassword(input.password), role: "lab_user", isActive: true, maxDevices: input.maxDevices }); return labId; }
export async function updateLabAdmin(input: { id: number; displayName: string; isActive: boolean; maxDevices: number; subscriptionStartDate?: string | null; subscriptionEndDate?: string | null }) { const db = await requireDb(); if (input.subscriptionStartDate && input.subscriptionEndDate && input.subscriptionEndDate < input.subscriptionStartDate) throw new Error("تاريخ انتهاء الاشتراك يجب أن يكون بعد تاريخ البداية."); await db.update(labs).set({ displayName: input.displayName.trim(), isActive: input.isActive, maxDevices: input.maxDevices, subscriptionStartDate: input.subscriptionStartDate ?? null, subscriptionEndDate: input.subscriptionEndDate ?? null }).where(eq(labs.id, input.id)); return { success: true }; }
export async function listLabUsersAdmin(labId: number) { const db = await requireDb(); return db.select({ id: labUsers.id, username: labUsers.username, email: labUsers.email, role: labUsers.role, isActive: labUsers.isActive, mustChangePassword: labUsers.mustChangePassword, maxDevices: labUsers.maxDevices, lastSignedIn: labUsers.lastSignedIn, createdAt: labUsers.createdAt }).from(labUsers).where(eq(labUsers.labId, labId)).orderBy(desc(labUsers.createdAt)); }
export async function createLabUserAdmin(input: { labId: number; username: string; email?: string; password: string; maxDevices?: number }) { const db = await requireDb(); const [lab] = await db.select({ maxDevices: labs.maxDevices }).from(labs).where(eq(labs.id, input.labId)).limit(1); if (!lab) throw new Error("المختبر المحدد غير موجود."); const result = await db.insert(labUsers).values({ labId: input.labId, username: input.username.trim(), email: input.email?.trim() || null, passwordHash: hashPassword(input.password), role: "lab_user", isActive: true, maxDevices: input.maxDevices ?? lab.maxDevices }); return Number(result[0].insertId); }
export async function resetLabUserPasswordAdmin(input: { labId: number; userId: number; password: string }) { const db = await requireDb(); const [user] = await db.select({ id: labUsers.id }).from(labUsers).where(and(eq(labUsers.id, input.userId), eq(labUsers.labId, input.labId), eq(labUsers.role, "lab_user"))).limit(1); if (!user) throw new Error("حساب المستخدم غير موجود ضمن هذا المختبر."); await db.update(labUsers).set({ passwordHash: hashPassword(input.password), mustChangePassword: true, sessionVersion: sql`${labUsers.sessionVersion} + 1` }).where(eq(labUsers.id, input.userId)); return { success: true }; }
export async function setLabUserActiveAdmin(input: { labId: number; userId: number; isActive: boolean }) { const db = await requireDb(); const [user] = await db.select({ id: labUsers.id, role: labUsers.role }).from(labUsers).where(and(eq(labUsers.id, input.userId), eq(labUsers.labId, input.labId))).limit(1); if (!user || user.role !== "lab_user") throw new Error("لا يمكن تعديل حالة حساب المسؤول أو حساب لا يتبع هذا المختبر."); await db.update(labUsers).set({ isActive: input.isActive, sessionVersion: sql`${labUsers.sessionVersion} + 1` }).where(eq(labUsers.id, input.userId)); return { success: true } as const; }
export async function deleteSuspendedLabUserAdmin(input: { labId: number; userId: number }) { const db = await requireDb(); const [user] = await db.select({ id: labUsers.id, isActive: labUsers.isActive, role: labUsers.role }).from(labUsers).where(and(eq(labUsers.id, input.userId), eq(labUsers.labId, input.labId))).limit(1); if (!user || user.role !== "lab_user") throw new Error("لا يمكن حذف حساب المسؤول أو حساب لا يتبع هذا المختبر."); if (user.isActive) throw new Error("لا يمكن حذف حساب نشط. أوقف الحساب أولًا ثم أعد المحاولة."); await db.delete(labUsers).where(and(eq(labUsers.id, input.userId), eq(labUsers.labId, input.labId))); return { success: true } as const; }
export async function changeOwnPassword(session: LabSession, input: { currentPassword: string; newPassword: string }) { const db = await requireDb(); const [user] = await db.select({ passwordHash: labUsers.passwordHash, sessionVersion: labUsers.sessionVersion, role: labUsers.role, labId: labUsers.labId, username: labUsers.username }).from(labUsers).where(eq(labUsers.id, session.userId)).limit(1); if (!user || !verifyPassword(input.currentPassword, user.passwordHash)) throw new Error("كلمة المرور الحالية غير صحيحة."); const nextVersion = user.sessionVersion + 1; await db.update(labUsers).set({ passwordHash: hashPassword(input.newPassword), mustChangePassword: false, sessionVersion: nextVersion }).where(eq(labUsers.id, session.userId)); const nextSession = { userId: session.userId, labId: user.labId, role: user.role, username: user.username, sessionVersion: nextVersion } as LabSession; return { token: await createLabSession(nextSession), session: { ...nextSession, mustChangePassword: false } }; }
export async function listLabDevicesAdmin(labId: number) { const db = await requireDb(); return db.select({ id: labDevices.id, deviceLabel: labDevices.deviceLabel, registeredAt: labDevices.registeredAt, lastSeenAt: labDevices.lastSeenAt }).from(labDevices).where(eq(labDevices.labId, labId)).orderBy(desc(labDevices.lastSeenAt)); }
export async function removeLabDeviceAdmin(labId: number, id: number) { const db = await requireDb(); await db.delete(labDevices).where(and(eq(labDevices.labId, labId), eq(labDevices.id, id))); return { success: true }; }


export async function getCashboxStatement(labId: number, cashboxId: number, startDate: string, endDate: string) {
  const db = await requireDb();
  const cashbox = await getOwnedCashbox(labId, cashboxId);
  const [received, payouts, costs, supplierPaid, incoming, outgoing] = await Promise.all([
    db.select({ id: payments.id, date: payments.paymentDate, amount: payments.amountPaid, currencyCode: payments.currencyCode, notes: payments.notes, party: clients.doctorName }).from(payments).leftJoin(clients, eq(payments.clientId, clients.id)).where(and(eq(payments.labId, labId), eq(payments.cashboxId, cashboxId), eq(payments.currencyCode, cashbox.currencyCode), gte(payments.paymentDate, startDate), lte(payments.paymentDate, endDate))),
    db.select({ id: technicianPayouts.id, date: technicianPayouts.payoutDate, amount: technicianPayouts.amountPaid, currencyCode: technicianPayouts.currencyCode, notes: technicianPayouts.notes, party: technicians.techName }).from(technicianPayouts).leftJoin(technicians, eq(technicianPayouts.technicianId, technicians.id)).where(and(eq(technicianPayouts.labId, labId), eq(technicianPayouts.cashboxId, cashboxId), eq(technicianPayouts.currencyCode, cashbox.currencyCode), gte(technicianPayouts.payoutDate, startDate), lte(technicianPayouts.payoutDate, endDate))),
    db.select({ id: expenses.id, date: expenses.expenseDate, amount: expenses.amount, currencyCode: expenses.currencyCode, notes: expenses.notes, party: expenses.category }).from(expenses).where(and(eq(expenses.labId, labId), eq(expenses.cashboxId, cashboxId), eq(expenses.currencyCode, cashbox.currencyCode), gte(expenses.expenseDate, startDate), lte(expenses.expenseDate, endDate))),
    db.select({ id: supplierPayments.id, date: supplierPayments.paymentDate, amount: supplierPayments.amountPaid, currencyCode: supplierPayments.currencyCode, notes: supplierPayments.notes, party: suppliers.supplierName }).from(supplierPayments).leftJoin(suppliers, eq(supplierPayments.supplierId, suppliers.id)).where(and(eq(supplierPayments.labId, labId), eq(supplierPayments.cashboxId, cashboxId), eq(supplierPayments.currencyCode, cashbox.currencyCode), gte(supplierPayments.paymentDate, startDate), lte(supplierPayments.paymentDate, endDate))),
    db.select({ id: cashboxTransfers.id, date: cashboxTransfers.transferDate, amount: cashboxTransfers.amount, currencyCode: cashboxTransfers.currencyCode, notes: cashboxTransfers.notes, party: sql<string>`fromBox.cashboxName` }).from(cashboxTransfers).leftJoin(sql`cashboxes as fromBox`, sql`fromBox.id = ${cashboxTransfers.fromCashboxId}`).where(and(eq(cashboxTransfers.labId, labId), eq(cashboxTransfers.toCashboxId, cashboxId), eq(cashboxTransfers.currencyCode, cashbox.currencyCode), gte(cashboxTransfers.transferDate, startDate), lte(cashboxTransfers.transferDate, endDate))),
    db.select({ id: cashboxTransfers.id, date: cashboxTransfers.transferDate, amount: cashboxTransfers.amount, currencyCode: cashboxTransfers.currencyCode, notes: cashboxTransfers.notes, party: sql<string>`toBox.cashboxName` }).from(cashboxTransfers).leftJoin(sql`cashboxes as toBox`, sql`toBox.id = ${cashboxTransfers.toCashboxId}`).where(and(eq(cashboxTransfers.labId, labId), eq(cashboxTransfers.fromCashboxId, cashboxId), eq(cashboxTransfers.currencyCode, cashbox.currencyCode), gte(cashboxTransfers.transferDate, startDate), lte(cashboxTransfers.transferDate, endDate))),
  ]);
  const items = [
    ...received.map((row) => ({ ...row, kind: "إيداع" as const, direction: 1 })),
    ...incoming.map((row) => ({ ...row, kind: "تحويل وارد" as const, direction: 1 })),
    ...payouts.map((row) => ({ ...row, kind: "سحب فني" as const, direction: -1 })),
    ...costs.map((row) => ({ ...row, kind: "مصروف" as const, direction: -1 })),
    ...supplierPaid.map((row) => ({ ...row, kind: "سداد مورد" as const, direction: -1 })),
    ...outgoing.map((row) => ({ ...row, kind: "تحويل صادر" as const, direction: -1 })),
  ].sort((a, b) => a.date.localeCompare(b.date) || a.id - b.id);
  const openingBalance = Number(cashbox.openingBalance);
  const finalBalance = openingBalance + items.reduce((sum, item) => sum + Number(item.amount) * item.direction, 0);
  return { cashbox: { id: cashbox.id, name: cashbox.cashboxName, currencyCode: cashbox.currencyCode }, startDate, endDate, openingBalance: money(openingBalance), finalBalance: money(finalBalance), items: items.map((item) => ({ ...item, amount: money(Number(item.amount)), signedAmount: money(Number(item.amount) * item.direction) })) };
}
